Ingress Controller.diagram:
@startuml
!include https://raw.githubusercontent.com/plantuml-stdlib/C4-PlantUML/master/C4_Component.puml
LAYOUT_WITH_LEGEND()

Container_Boundary(ingress_controller, "Ingress Controller") {
    Component(api_gateway_router, "API Gateway Router", "Kubernetes Ingress / Istio Envoy", "Routes authenticated HTTPS traffic from users to internal clinical containers securely.")
    Component(tls_termination_and_security_policy_enforcer, "TLS Termination and Security Policy Enforcer", "TLS 1.3 / OAuth2 / OIDC", "Handles TLS 1.3 termination, edge token validation, and JWKS local caching.")
}

Rel(api_gateway_router, tls_termination_and_security_policy_enforcer, "Validates tokens and enforces security policies", "mTLS")

@enduml

Patient Registration Container.diagram:
@startuml
!include https://raw.githubusercontent.com/plantuml-stdlib/C4-PlantUML/master/C4_Component.puml
LAYOUT_WITH_LEGEND()

title Component diagram for the Patient Registration Container container

Container_Boundary("Patient Registration Container", "Patient Registration Container") {
    Component("Registration API Controller", "Registration API Controller", "Kubernetes Microservice / REST", "Manages patient admissions, onboarding, and demographic data capture requests from front-end users.")
    Component("Registration Service", "Registration Service", "Business Logic Engine", "Enforces HIPAA and GDPR compliance, handling registration workflows and separating patient registration from downstream clinical workflows.")
    Component("Audit Logging Client", "Audit Logging Client", "gRPC/TLS", "Sends asynchronous audit logs to WORM-compliant log storage.")
}

Rel("Registration API Controller", "Registration Service", "Processes workflows and validates demographic data")
Rel("Registration Service", "Audit Logging Client", "Dispatches compliance and audit events asynchronously", "gRPC/TLS")

@enduml

EMR Container.diagram:
@startuml
!include https://raw.githubusercontent.com/plantuml-stdlib/C4-PlantUML/master/C4_Component.puml
LAYOUT_WITH_LEGEND()

title Component diagram for the EMR Container container

Container_Boundary(emr_container, "EMR Container") {
    Component(EMR API Controller, "EMR API Controller", "Spring Boot / REST", "Exposes endpoints for electronic medical records management and patient history retrieval.")
    Component(EMR Business Logic Service, "EMR Business Logic Service", "Java / Microservice", "Handles core clinical logic, medical record validation, and data processing.")
    Component(Encryption & Persistence Module, "Encryption & Persistence Module", "Hibernate / AES-256", "Manages secure data encryption and communication with the hybrid databases.")
}

Rel(EMR API Controller, EMR Business Logic Service, "Delegates request processing")
Rel(EMR Business Logic Service, Encryption & Persistence Module, "Persists and retrieves encrypted medical records")

@enduml

Billing & Insurance Claim Container.diagram:
@startuml
!include https://raw.githubusercontent.com/plantuml-stdlib/C4-PlantUML/master/C4_Component.puml
LAYOUT_WITH_LEGEND()

Container_Boundary("Billing & Insurance Claim Container", "Billing & Insurance Claim Container") {
    Component(Claim Validation Controller, "Claim Validation Controller", "Microservice REST API / OpenAPI", "Handles incoming HTTP requests, validates claim schemas, and enforces RBAC for billing officers.")
    Component(Claim Processing Service, "Claim Processing Service", "Business Logic Microservice", "Core logic for processing financial transactions, managing claim submissions, and integrating with external clearinghouses.")
    Component(Encryption Manager, "Encryption Manager", "HashiCorp Vault / AWS KMS", "Handles envelope encryption and AES-256 data protection at rest and message-level encryption.")
}

Rel(Claim Validation Controller, Claim Processing Service, "Delegates validated claims for processing")
Rel(Claim Processing Service, Encryption Manager, "Requests cryptographic operations for data and messages")
@enduml

PostgreSQL/MySQL Hybrid Databases.diagram:
@startuml
!include https://raw.githubusercontent.com/plantuml-stdlib/C4-PlantUML/master/C4_Component.puml
LAYOUT_WITH_LEGEND()

Container_Boundary("PostgreSQL/MySQL Hybrid Databases", "PostgreSQL/MySQL Hybrid Databases") {
    Component(PatroniOrchestratorReplicationManager, "Patroni/Orchestrator Replication Manager", "Patroni / Orchestrator", "Manages semi-synchronous replication and automated failover for the database instances.")
    Component(PgBouncerConnectionPooler, "PgBouncer Connection Pooler", "PgBouncer", "Handles connection pooling to optimize database performance and concurrency.")
    Component(AuditLogger, "Audit Logger", "pgaudit / Syslog", "Generates and streams database audit logs to WORM-compliant storage.")
}

Rel(PatroniOrchestratorReplicationManager, PgBouncerConnectionPooler, "Maintains high availability across database nodes serving connections")
Rel(PgBouncerConnectionPooler, AuditLogger, "Transmits database transaction and access records")

@enduml

WORM-Compliant Log Storage.diagram:
@startuml
!include https://raw.githubusercontent.com/plantuml-stdlib/C4-PlantUML/master/C4_Component.puml
LAYOUT_WITH_LEGEND()

Container_Boundary(worm_compliant_log_storage, "WORM-Compliant Log Storage") {
    Component(Metadata_Indexing_Layer, "Metadata Indexing Layer", "PostgreSQL/MySQL Hybrid Databases", "Indexes audit log metadata for efficient querying and reporting while maintaining immutability guarantees.")
    Component(Local_Buffering_Proxy, "Local-Buffering Proxy", "Edge-Buffering Proxy with TPM/HSM-backed edge encryption", "Buffers asynchronous audit logs locally during intermittent network disconnections before forwarding securely.")
}

Rel(Local_Buffering_Proxy, Metadata_Indexing_Layer, "Indexes incoming asynchronous audit logs", "gRPC/TLS with mTLS")

@enduml
